    H,W=len(gin),len(gin[0])
    F={(i,j) for i in range(H) for j in range(W) if gin[i][j]==4}
    S={(i,j) for i in range(H) for j in range(W) if gin[i][j]==6}
    ar=min(i for i,_ in F); am=max(i for i,_ in F); arc=min(j for _,j in F); amc=max(j for _,j in F)
    mr=(min(i for i,_ in S)+max(i for i,_ in S))/2; mc=(min(j for _,j in S)+max(j for _,j in S))/2
    dr=round(mr-(ar+am)/2); dc=round(mc-(arc+amc)/2)
    # flip axis: pick axis whose displacement component is smaller -> flip there; else towards larger?
    best=None
    if abs(dr)>=abs(dc):
        P=[(ar+am-i,j) for i,j in F]
        for dy in [-1,1]:
            C=[(ar+dy+i,j) for i,j in P]
            Cset={(a,b) for a,b in C}
            def dist(C,S,Cset):
                return min(abs(a-s[0])+abs(b-s[1]) for a,b in C for s in S)- (1 if any((a,b) in S for a,b in C) else 0)
            sc=dist(C,S,Cset)
            key=(-sc,dy)
            if best is None or key<best[0]: best=(key,(dy,'v'))
    else:
        P=[(i,arc+amc-j) for i,j in F]
        for dx in [-1,1]:
            C=[(i,arc+dx+j) for i,j in P]
            Cset={(a,b) for a,b in C}
            sc=min(abs(a-s[0])+abs(b-s[1]) for a,b in C for s in S)-(1 if any((a,b) in S for a,b in C) else 0)
            key=(-sc,dx)
            if best is None or key<best[0]: best=(key,(dx,'h'))
    dy,dir_=best[1]
    C=set()
    if dir_=='v':
        P=[(ar+am-i,j) for i,j in F]
        C={(ar+(1 if dy==1 else -1)+i,j) for i,j in P}
    else:
        P=[(i,arc+amc-j) for i,j in F]
        C={(i,arc+(1 if dy==1 else -1)+j) for i,j in P}
    out=[[0]*W for _ in range(H)]
    for i,j in F: out[i][j]=4
    C=F&C  # erase markers not covered by copy
    for i,j in (S-F-C): out[i][j]=0
    for i,j in (C-S+F): pass
    return out
